<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\AuditService;
class CareerController extends Controller {
    private function leader($id){ return DB::table('leaders')->where('leader_id',$id)->firstOrFail(); }
    public function create($leaderId){ $leader=$this->leader($leaderId); $next=(int)DB::table('career_history')->where('leader_id',$leaderId)->max('seq')+1; return view('admin.career.form',compact('leader','next')+['career'=>null,'mode'=>'create']); }
    public function store(Request $r,$leaderId){ $this->leader($leaderId); $d=$r->validate(['seq'=>'required|integer|min:1','position'=>'nullable|string','department'=>'nullable|string','province'=>'nullable|string','start_year'=>'nullable|integer|min:1800|max:2100','end_year'=>'nullable|integer|min:1800|max:2100']); if(DB::table('career_history')->where(['leader_id'=>$leaderId,'seq'=>$d['seq']])->exists()) return back()->withInput()->withErrors(['seq'=>'Sequence already exists for this leader.']); DB::table('career_history')->insert(array_merge(['leader_id'=>$leaderId],$d)); AuditService::log('created','career_history',$leaderId.':'.$d['seq'],null,array_merge(['leader_id'=>$leaderId],$d),'Career record added'); return redirect()->route('admin.leaders.show',$leaderId)->with('success','Career record added.'); }
    public function edit($leaderId,$seq){ $leader=$this->leader($leaderId); $career=DB::table('career_history')->where(['leader_id'=>$leaderId,'seq'=>$seq])->firstOrFail(); return view('admin.career.form',compact('leader','career')+['next'=>$seq,'mode'=>'edit']); }
    public function update(Request $r,$leaderId,$seq){ $this->leader($leaderId); $d=$r->validate(['seq'=>'required|integer|min:1','position'=>'nullable|string','department'=>'nullable|string','province'=>'nullable|string','start_year'=>'nullable|integer|min:1800|max:2100','end_year'=>'nullable|integer|min:1800|max:2100']); $old=(array)DB::table('career_history')->where(['leader_id'=>$leaderId,'seq'=>$seq])->first(); DB::transaction(function()use($leaderId,$seq,$d){ if((int)$d['seq'] !== (int)$seq && DB::table('career_history')->where(['leader_id'=>$leaderId,'seq'=>$d['seq']])->exists()) abort(422,'Sequence already exists.'); DB::table('career_history')->where(['leader_id'=>$leaderId,'seq'=>$seq])->update($d); }); AuditService::log('updated','career_history',$leaderId.':'.$seq,$old,$d,'Career record updated'); return redirect()->route('admin.leaders.show',$leaderId)->with('success','Career record updated.'); }
    public function destroy($leaderId,$seq){ $this->leader($leaderId); $old=(array)DB::table('career_history')->where(['leader_id'=>$leaderId,'seq'=>$seq])->first(); DB::table('career_history')->where(['leader_id'=>$leaderId,'seq'=>$seq])->delete(); AuditService::log('deleted','career_history',$leaderId.':'.$seq,$old,null,'Career record deleted'); return back()->with('success','Career record deleted.'); }
    public function bulkDestroy(Request $r,$leaderId){ $this->leader($leaderId); $seqs=(array)$r->input('seqs'); $r->validate(['seqs'=>'required|array|min:1']); DB::table('career_history')->where('leader_id',$leaderId)->whereIn('seq',$seqs)->delete(); return back()->with('success',count($seqs).' career records deleted.'); }
}
